import { AgentDeadlineError } from "../agent/loop-errors.js";
import { finishDiagnosis } from "../commands/diagnose.js";
import { finishReview } from "../commands/review.js";
import { publishTaskAnswer } from "../commands/task.js";
import { PolicyDeniedError } from "../errors.js";
import { throwIfCancelled } from "../lifecycle/cancellation.js";
import { PHASE_TIMEOUTS, phaseTimeoutMs } from "../lifecycle/deadline.js";
import { revalidatePullRequestHead } from "../write/pr.js";
import { inspectWorkspaceChanges } from "../write/workspace.js";
import { executeWrite } from "./write.js";
export function prepareReviewOperation(options) {
    const { client, repository, snapshot, lifecycle } = options;
    let publication;
    return {
        snapshot: () => (publication === undefined ? {} : { publication }),
        async finalize(result) {
            lifecycle.enter("publication");
            await lifecycle.update("finalizing", "Structured output passed validation. Mapping findings to the current diff and publishing.");
            await revalidatePullRequestHead(client, repository.owner, repository.repo, snapshot.number, snapshot.headSha);
            await options.revalidateAuthority();
            publication = await finishReview(client, {
                ...repository,
                pullNumber: snapshot.number,
                expectedAuthorId: options.expectedAuthorId,
                runUrl: options.runUrl,
            }, snapshot, result, options.maxFindings, (confirmed) => {
                publication = confirmed;
            });
            return { kind: "review", publication };
        },
    };
}
export function prepareDiagnosisOperation(options) {
    let commentId;
    return {
        snapshot: () => (commentId === undefined ? {} : { commentId }),
        async finalize(result) {
            options.lifecycle.enter("publication");
            await options.lifecycle.update("finalizing", "Structured output passed validation. Publishing the bounded CI diagnosis.");
            if (options.issueNumber !== undefined) {
                await options.revalidateAuthority();
                commentId = await finishDiagnosis(options.client, { ...options.repository, issueNumber: options.issueNumber }, options.expectedAuthorId, result, options.runUrl);
            }
            return { kind: "diagnose" };
        },
    };
}
/** Task and write operations share workspace inspection, validation and write ordering. */
export function prepareWorkspaceOperation(options) {
    const { authorized, inputs, workspaceCopy, boundWriteSha, lifecycle, validation, githubAuthority, signal, } = options;
    const { client, context, command, policy, snapshot } = authorized;
    let effects = {};
    return {
        snapshot: () => ({ ...effects }),
        async finalize(agentResult, remainingMs) {
            // Each candidate gets one validation budget; a repair turn starts a new candidate.
            let validationBudget;
            const remainingControllerMs = () => {
                throwIfCancelled(signal);
                const remaining = Math.min(remainingMs, options.deadlineMs - Date.now());
                if (remaining <= 0)
                    throw new AgentDeadlineError();
                return remaining;
            };
            const controllerValidationBudget = () => {
                throwIfCancelled(signal);
                if (validationBudget === undefined) {
                    const phaseMs = Math.min(remainingControllerMs(), phaseTimeoutMs(options.deadlineMs, PHASE_TIMEOUTS.validationMs, Date.now));
                    validationBudget = { deadlineMs: Date.now() + phaseMs, signal };
                }
                return validationBudget;
            };
            const changes = workspaceCopy === undefined ? undefined : await inspectWorkspaceChanges(workspaceCopy);
            if (changes?.all.length === 0 && command.requestedAccess === "write") {
                lifecycle.enter("validation");
                remainingControllerMs();
                await validation?.inspect(changes, controllerValidationBudget());
            }
            if (command.operation === "task") {
                if ((changes?.all.length ?? 0) === 0) {
                    remainingControllerMs();
                    await githubAuthority?.flush(remainingControllerMs());
                    lifecycle.enter("publication");
                    await authorized.revalidateAuthority();
                    const commentId = options.issueNumber === undefined
                        ? undefined
                        : await publishTaskAnswer(client, {
                            owner: context.repository.owner,
                            repo: context.repository.repo,
                            issueNumber: options.issueNumber,
                        }, inputs.botUserId, agentResult, options.runUrl);
                    if (commentId !== undefined)
                        effects = { ...effects, commentId };
                    return {
                        kind: "answer",
                        ...(command.requestedAccess === "write" ? { noChanges: true } : {}),
                        ...(commentId === undefined ? {} : { commentId }),
                    };
                }
                if (!policy.capabilities.modifyWorkspace) {
                    throw new PolicyDeniedError("A read-only task produced workspace changes; refusing publication");
                }
            }
            if (workspaceCopy === undefined ||
                boundWriteSha === undefined ||
                validation === undefined ||
                changes === undefined) {
                throw new Error("Write operation requires a trusted checked-out workspace");
            }
            lifecycle.enter("validation");
            await lifecycle.update("finalizing", "The structured change is ready. Running configured validation before any GitHub write.");
            remainingControllerMs();
            const budget = controllerValidationBudget();
            const validateWorkspace = await validation.prepareWrite(changes, budget);
            const write = await executeWrite({
                authorized,
                inputs,
                workspaceCopy,
                boundWriteSha,
                agentResult,
                validationDeadlineMs: budget.deadlineMs,
                taskIdentity: options.taskIdentity,
                onPhase: (phase) => lifecycle.enter(phase),
                validateWorkspace,
                onValidationPassed: (receipt) => {
                    if (receipt.kind === "completed-operation")
                        validation.completedOperation();
                },
                onBranchConfirmed: (receipt) => {
                    effects = { ...effects, ...receipt, writeStatus: "partial-success" };
                },
                signal,
            });
            effects = { ...effects, ...write, writeStatus: "partial-success" };
            if (snapshot?.kind === "pull_request" && write.commitSha !== undefined) {
                githubAuthority?.advanceValidatedPullHead(write.commitSha, snapshot.headRef);
            }
            await githubAuthority?.flush(remainingControllerMs());
            return { kind: "write", write };
        },
    };
}
